import json
input_grid = [
    [1, 1, 1, 1, 5, 2, 0, 0, 0],
    [0, 1, 1, 0, 5, 2, 2, 2, 2],
    [0, 1, 1, 0, 5, 2, 0, 0, 0],
    [0, 0, 0, 0, 5, 0, 0, 0, 0]
]

# When either side has a full bar, BOTH sides get full bars
# When neither has a full bar, keep original
output = []
for row in input_grid:
    left_full = row[:4] == [1]*4
    right_full = row[5:9] == [2]*4

    if left_full or right_full:
        # Which color for each side?
        if left_full:
            left_color = 1
        else:
            left_color = (1 if right_full else 0)  # If right was full, use 1 for symmetry

        if right_full:
            right_color = 2
        else:
            right_color = (2 if left_full else 0)

        new_row = [left_color]*4 + [row[4]] + [right_color]*4
    else:
        new_row = row
    output.append(new_row)

for row in output:
    print(' '.join(map(str, row)))
print(json.dumps({"action": "submit", "grid": output}))
